/**
 * server/brain/capabilityCatalog.js
 *
 * Serves the generated command catalogue to the Editorial Brain, and turns it
 * into the prompt's capability section.
 *
 * Replaces the hand-maintained list that carried this note:
 *   "NOTE: this list is maintained by hand and must match the action registry
 *    … add it here too, or the Brain will never suggest it."
 * It had drifted to 14 entries against 61 registered commands.
 *
 * The catalogue itself is generated by scripts/generate_capability_catalog.mjs
 * from client/src/agent/CommandRegistry.js, and test_capability_graph.mjs
 * fails if the committed JSON falls out of sync — so the Brain's vocabulary
 * now cannot drift from what the app can actually do.
 *
 * Pure, no I/O beyond the one require of a committed JSON file.
 */

'use strict';

const catalog = require('./commandCatalog.generated.json');

/**
 * Resources this module can actually determine from the server's context
 * object (built by ContextEngine).
 *
 * The client's CapabilityGraph derives all 13 resources from the live Zustand
 * store. The server only receives a projectState summary, so it can see seven
 * of them. The other six (selection, shadow, blurZone, keywordEmphasis,
 * brandKit, history) are invisible here — and a command gated on one of those
 * must NOT be reported as blocked, because "I can't see it" is not "it isn't
 * there". Those commands are listed as available; the Brain is told not to
 * assume, and MediaExecutionEngine remains the authority at run time.
 */
const DETERMINABLE = Object.freeze([
    'clips', 'assets', 'transcript', 'captionClips',
    'diarization', 'sceneAnalysis', 'colorGrade',
]);

/**
 * Which resources the project has, as far as the server can tell.
 *
 * @param {Object} ctx  ContextEngine.build() output
 * @returns {Set<string>}
 */
function deriveResources(ctx) {
    const c = ctx || {};
    const have = new Set();

    if ((Number(c.clipCount) || 0) > 0) have.add('clips');
    if ((Number(c.totalAssets) || 0) > 0) have.add('assets');

    // Server-side `hasCaptions` is captions.length > 0 — i.e. the transcript
    // words, which is also what unlocks every transcript-gated command.
    if (c.hasCaptions) have.add('transcript');

    // The server payload doesn't distinguish transcript words from placed
    // caption clips, so this is the closest honest signal: either captions
    // exist, or the ledger says auto_captions ran.
    const editsDone = Array.isArray(c.editsDone) ? c.editsDone : [];
    if (c.hasCaptions || editsDone.includes('auto_captions')) have.add('captionClips');

    const speakers = (Number(c.detectedSpeakers) || 0) || (Number(c.effects && c.effects.speakerCount) || 0);
    if (speakers > 0) have.add('diarization');

    if ((Number(c.analyzedAssets) || 0) > 0) have.add('sceneAnalysis');
    if (c.hasColorGrade || c.projectLUTId) have.add('colorGrade');

    return have;
}

/**
 * The phrase to run to produce a resource, or null when no command can: those
 * need a user action (uploading footage), and the graph deliberately refuses to
 * auto-insert a command that would invent content to satisfy them.
 */
const PRODUCER_PHRASE = Object.freeze({
    transcript:    'Add captions',
    captionClips:  'Add captions',
    diarization:   'detect speakers',
    sceneAnalysis: 'analyze the framing',
    clips:         null,
    assets:        null,
});

/**
 * Plain-English names for the resource vocabulary. Without these the prompt
 * leaks internal identifiers ("BLOCKED: needs colorGrade"), which then show up
 * in the Brain's own prose to the user.
 */
const RESOURCE_NAME = Object.freeze({
    clips:            'clips on the timeline',
    assets:           'footage in the bin',
    transcript:       'a transcript',
    captionClips:     'captions on the timeline',
    diarization:      'speaker detection',
    sceneAnalysis:    'framing analysis',
    colorGrade:       'a colour grade',
    selection:        'a selected clip',
    keywordEmphasis:  'highlighted key words',
    shadow:           'a drop shadow',
    blurZone:         'a blur zone',
    brandKit:         'a saved brand kit',
    history:          'an earlier change to undo',
});

/**
 * Resources the USER supplies by acting outside the editor (uploading). No
 * command produces these, so the fix is a request to them, not a step to run.
 */
const USER_SUPPLIED = Object.freeze(['clips', 'assets']);

const resourceName = (key) => RESOURCE_NAME[key] || key;

/**
 * How to phrase an unmet requirement.
 *
 * Three shapes, because one template produced nonsense: a flat "the user has
 * to add X" rendered colorGrade as "the user has to add a colour grade already
 * applied". An unmet requirement is either something a command produces,
 * something the user must upload, or a state that has to exist already — and
 * each needs different words.
 */
function fixPhrase(resource) {
    if (PRODUCER_PHRASE[resource]) return `run "${PRODUCER_PHRASE[resource]}" first`;
    if (USER_SUPPLIED.includes(resource)) return `the user has to add ${resourceName(resource)}`;
    return `only applies once there is ${resourceName(resource)}`;
}

/**
 * Split the catalogue into what can run now and what is gated.
 *
 * @param {Object} ctx
 * @returns {{ready: Object[], blocked: Array<{command: Object, missing: string[]}>}}
 */
function partition(ctx) {
    const have = deriveResources(ctx);
    const ready = [];
    const blocked = [];

    for (const cmd of catalog.commands) {
        // Only requirements the server can actually evaluate count against a
        // command; an unknowable one is left to run-time validation.
        const missing = (cmd.requires || [])
            .filter(r => DETERMINABLE.includes(r))
            .filter(r => !have.has(r));
        if (missing.length === 0) ready.push(cmd);
        else blocked.push({ command: cmd, missing });
    }

    return { ready, blocked };
}

const trim = (text, max) => {
    const s = String(text || '').replace(/\s+/g, ' ').trim();
    return s.length <= max ? s : s.slice(0, max - 1).trimEnd() + '…';
};

/**
 * The prompt's capability section, written against the live project so the
 * Brain is told what is possible NOW rather than what exists in the abstract.
 *
 * @param {Object} ctx  ContextEngine.build() output
 * @returns {string}
 */
function commandsPromptSection(ctx) {
    const { ready, blocked } = partition(ctx);
    const styleId = typeof ctx?.editingStyle === 'string' ? ctx.editingStyle : ctx?.editingStyle?.id;
    const style = catalog.styles?.[styleId] || null;
    const mode = catalog.modes?.[ctx?.editingMode] || null;

    const line = (cmd) => {
        const inputs = (cmd.inputs || []).filter(input => input.name).map(input => input.name);
        return `  "${cmd.phrase}" → ${cmd.id}${cmd.destructive ? ' [cuts footage]' : ''}${inputs.length ? ` [inputs: ${inputs.join(', ')}]` : ''} — ${trim(cmd.summary || cmd.label, 62)}`;
    };

    /**
     * The one sentence that unblocks a command.
     * Resources with no producer (clips, assets) need a user action, so they
     * read as "upload footage", not as a command to propose.
     */
    const fixFor = (missing) => missing
        .map(fixPhrase)
        .filter((v, i, a) => a.indexOf(v) === i)
        .join(', then ');

    /**
     * Blocked commands GROUPED BY their fix rather than listed one per line.
     *
     * One line per command cost ~54 lines on an empty project — most of them
     * repeating the same "run Add captions first" — which is both token waste
     * and worse guidance: the useful fact is "these eleven things all unlock
     * together", not eleven separate dead ends.
     */
    const blockedSection = (items) => {
        const groups = new Map();
        for (const item of items) {
            const fix = fixFor(item.missing);
            if (!groups.has(fix)) groups.set(fix, []);
            groups.get(fix).push(item.command.id);
        }
        return [...groups.entries()]
            // Biggest unlock first: it is the highest-value thing to propose.
            .sort((a, b) => b[1].length - a[1].length || a[0].localeCompare(b[0]))
            .map(([fix, ids]) => `  ${fix} — unlocks ${ids.length}: ${ids.sort().join(', ')}`)
            .join('\n');
    };

    const byCategory = (list, render) => {
        const groups = new Map();
        for (const item of list) {
            const key = (item.command || item).category;
            if (!groups.has(key)) groups.set(key, []);
            groups.get(key).push(item);
        }
        return [...groups.entries()]
            .sort((a, b) => a[0].localeCompare(b[0]))
            .map(([cat, items]) => `${cat}:\n${items.map(render).join('\n')}`)
            .join('\n');
    };

    const parts = [
        '═══════════════════════════════════════════════',
        `WHAT YOU CAN ASK FOR (${catalog.commandCount} operations, generated from the command registry)`,
        '═══════════════════════════════════════════════',
        'Put the QUOTED PHRASE in suggestion.command and intent.command, exactly as',
        'written. Each one is verified to resolve to the operation named after it, so a',
        'quoted phrase always runs; an id or an invented paraphrase makes the parser guess.',
        'Use the phrase for suggestion.text too, or your own wording of the same request.',
        '',
        `READY ON THIS PROJECT (${ready.length}):`,
        byCategory(ready, line),
    ];

    if (style) {
        const readyIds = new Set(ready.map(command => command.id));
        const styleCommands = (style.preferredCommands || []).filter(id => readyIds.has(id));
        parts.push(
            '',
            `ACTIVE EDITING STYLE: ${style.label}${style.platform ? ` (platform: ${style.platform})` : ''}.`,
            `Use this style to fill unspecified choices; explicit user instructions take priority.`,
            `Style defaults: ${style.keepsRecordedOrder ? 'preserve recorded order' : 'a stronger opening may be selected when the request calls for it'}; ${style.calm ? 'keep motion and transitions restrained' : 'motion may follow the requested energy'}; sound effects: ${style.sfxLevel}; ${style.expectsMusic ? 'music can be part of the style' : 'do not add music unless requested'}.`,
            `Style-aligned commands available now: ${styleCommands.length ? styleCommands.join(', ') : 'none of its preferred commands are currently ready; check prerequisites above'}.`,
        );
    }

    if (mode) {
        parts.push(
            '',
            `EDITING MODE: ${mode.label}.`,
            mode.planning,
            mode.execution,
        );
    }

    if (blocked.length > 0) {
        parts.push(
            '',
            `NOT YET POSSIBLE (${blocked.length}) — propose the fix, never the blocked operation:`,
            blockedSection(blocked),
        );
    }

    parts.push(
        '',
        'Rules for this list:',
        '- NEVER propose an operation that is not on it. If the right fix is not here,',
        '  say so as advice and describe what the user should do by hand.',
        '- A BLOCKED operation is not a suggestion. Propose what unblocks it.',
        '- "[cuts footage]" removes material. Only propose one when the user asked to',
        '  shorten, clean or tighten something.',
        '- Commands gated on a selection, a shadow, a blur zone, keyword highlights, a',
        '  brand kit or undo history are listed as ready because this prompt cannot see',
        '  those. Do not assert they are present — offer, or ask.',
        '- Never claim an edit succeeded from this advisory response. The execution',
        '  pipeline must run the command and verify its postcondition first.',
    );

    return parts.join('\n');
}

module.exports = {
    catalog,
    DETERMINABLE,
    RESOURCE_NAME,
    USER_SUPPLIED,
    PRODUCER_PHRASE,
    fixPhrase,
    deriveResources,
    partition,
    commandsPromptSection,
};
